# -*- coding: utf-8 -*-
"""Lecture 30 vignette pool C -- Arrhythmias II: ventricular tachycardia,
torsades de pointes and QT prolongation, ventricular fibrillation, asystole and
pulseless electrical activity.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes with a varied lead-in. What she stressed is in several
stems: instability (chest pain, altered mental status, dyspnea, hypotension)
turns a pulse-present ventricular tachycardia into synchronized cardioversion;
polymorphic ventricular tachycardia is never stable and is defibrillated;
torsades is "mag, mag, mag". No dose, shock count or drug interval is keyed,
no drug from the QT list is named, and calcium and bicarbonate never appear.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l30_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


VT = "Ventricular tachycardia"
TDP = "Torsades and QT prolongation"
VF = "Ventricular fibrillation"
ASY = "Asystole and pulseless electrical activity"
